# ruff: noqa: E501
from uuid import UUID

from fastapi import APIRouter
from fastapi.responses import HTMLResponse

from newsintel.api.dependencies import ViewerAuth
from newsintel.api.ui import COMMON_JS, render_app_page
from newsintel.domain.access import Permission

router = APIRouter(tags=["article-intelligence-dashboard"])


@router.get("/articles/{article_id}/intelligence", response_class=HTMLResponse)
async def article_intelligence_dashboard(article_id: UUID, auth: ViewerAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "viewer")
    evolution_button = (
        f'<a class="button secondary" href="/articles/{article_id}/evolution">Article evolution</a>'
        if Permission.CLAIMS_VIEW.value in auth.permissions
        else ""
    )
    workspace_button = (
        f'<a class="button ghost" href="/investigations?add_type=article&add_id={article_id}">Add to workspace</a>'
        if Permission.CLAIMS_VIEW.value in auth.permissions
        else ""
    )
    body = f"""
<section class="page-head"><div><div class="eyebrow">Report details</div><h1 id="headline"><span class="skeleton" style="display:block;width:min(720px,80vw);height:46px"></span></h1><div id="meta" class="muted"></div></div><div class="toolbar"><span><span id="liveDot" class="status-dot"></span> <span id="liveText" class="muted small">Connecting</span></span>{evolution_button}{workspace_button}<a class="button secondary" href="/news">All reports</a></div></section>
<section id="alertArea" aria-live="polite"></section>
<section class="panel" id="heroPanel"><div id="statePills" class="pill-row"></div><div class="grid three" id="metrics" style="margin-top:14px"><div class="metric"><div class="skeleton"></div></div><div class="metric"><div class="skeleton"></div></div><div class="metric"><div class="skeleton"></div></div></div><div class="toolbar" style="margin-top:14px"><a id="sourceLink" class="button" target="_blank" rel="noopener noreferrer">Open original source</a><a id="eventLink" class="button secondary">Open event</a></div></section>
<section class="panel" style="padding-bottom:0"><div class="tabs" role="tablist" aria-label="Article intelligence sections"><button class="tab active" data-tab="overview" type="button" role="tab" aria-selected="true">Overview</button><button class="tab" data-tab="claims" type="button" role="tab" aria-selected="false">Claims</button><button class="tab" data-tab="history" type="button" role="tab" aria-selected="false">Historical context</button><button class="tab" data-tab="evidence" type="button" role="tab" aria-selected="false">Evidence</button><button class="tab" data-tab="source" type="button" role="tab" aria-selected="false">Source text</button></div>
  <div id="tab-overview" class="tab-panel active"><div class="grid two"><section><div class="section-head"><h2>What changed</h2></div><div id="changeSummary"><div class="skeleton" style="height:70px"></div></div><div class="section-head" style="margin-top:22px"><h2>Related earlier coverage</h2></div><div id="topHistory" class="timeline"><div class="skeleton" style="height:100px"></div></div></section><section><div class="section-head"><h2>Evidence available</h2><span class="muted small">Links found · not a truth score</span></div><div id="quality"><div class="skeleton" style="height:180px"></div></div></section></div></div>
  <div id="tab-claims" class="tab-panel"><div class="section-head"><div><h2>Claims & verification</h2><div class="muted small">Expand a claim to inspect its supporting or conflicting evidence.</div></div><select id="claimFilter" style="width:auto"><option value="all">All claims</option><option value="supported">Supported</option><option value="unverified">Unverified</option><option value="disputed">Disputed</option><option value="contradicted">Contradicted</option></select></div><div id="claims"><div class="skeleton" style="height:160px"></div></div></div>
  <div id="tab-history" class="tab-panel"><div class="section-head"><div><h2>Story timeline</h2><div class="muted small">Historical items are links/context, not automatic proof.</div></div><select id="timelineOrder" style="width:auto"><option value="asc">Oldest first</option><option value="desc">Newest first</option></select></div><div id="timeline" class="timeline"><div class="skeleton" style="height:180px"></div></div></div>
  <div id="tab-evidence" class="tab-panel"><div class="section-head"><h2>Linked evidence</h2></div><div id="evidenceMap" class="stack"><div class="skeleton" style="height:160px"></div></div></div>
  <div id="tab-source" class="tab-panel"><div class="section-head"><h2>Captured article text</h2><span id="methodNote" class="muted small"></span></div><div id="pdfDocumentReview" hidden></div><div id="articleBody" class="prose prose-box">Loading extracted text…</div></div>
</section>
"""
    article_id_text = str(article_id)
    scripts = f"""<script>{COMMON_JS}
const articleId={article_id_text!r};let lastState=null;let articleData=null;let claimsData=null;let qualityData=null;let historyData=null;
function stateKind(s){{if(s==='ready')return 'good';if(s==='review_required')return 'bad';if(s==='ready_with_warnings')return 'warn';return 'warn'}}
function humanPattern(v){{const m={{mostly_new_reporting:'Mostly new reporting',material_update:'Material update',continuity_with_prior_reporting:'Continuity with prior reporting',possible_conflict_or_revision:'Possible conflict or revision',no_checkable_claims:'No checkable claims'}};return m[v]||niTitle(v||'Analysis pending')}}
function readinessLabel(v){{if(typeof v!=='number')return 'Unavailable';if(v>=.8)return 'Strong';if(v>=.6)return 'Moderate';if(v>=.4)return 'Limited';return 'Weak'}}
function linkageLabel(h){{const c=h?.context_summary?.historical_context_confidence;return c?.label?niTitle(c.label):'Pending'}}
niInitTabs();
async function loadCore(){{try{{const [article,state]=await Promise.all([niApi(`/api/v1/articles/${{articleId}}`),niApi(`/api/v1/articles/${{articleId}}/intelligence-state`)]);articleData=article;historyData=article.historical_context;renderCore(article,state);renderHistory(historyData)}}catch(e){{document.getElementById('headline').textContent='Unable to load article';document.getElementById('alertArea').innerHTML=`<div class="error-box">${{niEsc(e.message)}}</div>`;throw e}}}}
async function loadAnalystPanels(){{const [claims,quality]=await Promise.all([niOptional(`/api/v1/articles/${{articleId}}/claims`),niOptional(`/api/v1/articles/${{articleId}}/quality`)]);claimsData=claims;qualityData=quality;if(claims)renderClaims();else{{document.getElementById('claims').innerHTML='<div class="notice">Analyst access is required to view extracted claims and evidence.</div>';document.getElementById('evidenceMap').innerHTML='<div class="notice">Analyst access is required to inspect evidence relationships.</div>'}}if(quality)renderQuality();else document.getElementById('quality').innerHTML='<div class="notice">Analyst access is required to view evidence-readiness dimensions.</div>'}}
function renderCore(a,s){{document.getElementById('headline').textContent=a.title;document.title=`${{a.title}} · News Intelligence`;document.getElementById('meta').textContent=`${{a.language||'language unknown'}} · published ${{niDate(a.published_at)}} · observed ${{niDate(a.first_observed_at)}}`;document.getElementById('sourceLink').href=niSafeUrl(a.canonical_url);const eventLink=document.getElementById('eventLink');if(a.event_id)eventLink.href=`/events/${{a.event_id}}/intelligence`;else eventLink.hidden=true;const v=a.latest_version;const fidelity=String(v?.extraction_fidelity_label||'').toLowerCase();const fidelityPill=fidelity?niPill(`Publisher fidelity: ${{niTitle(fidelity)}}`,fidelity==='strong'?'good':fidelity==='moderate'?'warn':'bad'):'';document.getElementById('statePills').innerHTML=niPill(niTitle(s.state),stateKind(s.state))+niPill(`History: ${{niTitle(s.historical_state||'pending')}}`,['complete','internal_only'].includes(s.historical_state)?'good':'warn')+fidelityPill+(s.historical_depth?niPill(`Depth: ${{niTitle(s.historical_depth)}}`):'')+(v?.browser_rendered?niPill('Browser recovered','warn'):'')+(s.historical_change_pattern?niPill(humanPattern(s.historical_change_pattern),s.historical_change_pattern==='possible_conflict_or_revision'?'warn':'neutral'):'');document.getElementById('articleBody').textContent=v?.text_content||'No extracted body is available.';renderDocumentReview(v);document.getElementById('methodNote').textContent=v?`${{niTitle(v.extraction_method)}} · ${{v.word_count}} words${{v.browser_rendered?' · browser recovered':''}}${{fidelity?` · publisher fidelity ${{niTitle(fidelity)}}`:''}}`:'';const fidelityIssues=v?.extraction_fidelity_discrepancies||[];if(s.state==='review_required')document.getElementById('alertArea').innerHTML='<div class="notice bad"><b>Review required.</b> One or more claims are stale, corrected, retracted or otherwise need analyst review.</div>';else if(fidelity==='weak')document.getElementById('alertArea').innerHTML=`<div class="notice bad"><b>Extraction fidelity is weak.</b> ${{fidelityIssues.length?niEsc(fidelityIssues.map(niTitle).join(' · ')):'Publisher metadata and extracted content disagree materially.'}}</div>`;else if(s.state==='ready_with_warnings'||fidelity==='moderate')document.getElementById('alertArea').innerHTML='<div class="notice warn"><b>Ready with warnings.</b> The story is available, but some extraction or enrichment checks need attention.</div>';else document.getElementById('alertArea').innerHTML='';updateMetrics(s)}}
function updateMetrics(s){{const q=qualityData;const h=historyData;const hc=h?.context_summary?.historical_context_confidence||{{}};document.getElementById('metrics').innerHTML=`<div class="metric"><div class="label">Evidence readiness</div><div class="value">${{q?readinessLabel(q.overall_evidence_readiness):'Analyzing'}}</div><div class="hint">${{q?`${{q.verified_claim_count}}/${{q.checkable_claim_count}} checkable claims verified`:'Analyst view or analysis pending'}}</div></div><div class="metric"><div class="label">Historical linkage</div><div class="value">${{niEsc(linkageLabel(h))}}</div><div class="hint">${{h?`${{(h.same_event_history||[]).length+(h.internal_matches||[]).length+(h.external_matches||[]).length}} linked records`:'Historical enrichment pending'}}</div></div><div class="metric"><div class="label">Current state</div><div class="value">${{niEsc(niTitle(s.state))}}</div><div class="hint">${{s.review_required_claim_count||0}} review required</div></div>`}}
function renderQuality(){{const q=qualityData;if(!q)return;document.getElementById('quality').innerHTML=`<div class="notice"><b>${{readinessLabel(q.overall_evidence_readiness)}} evidence readiness.</b> This summarizes coverage/reproducibility and is not a factual-truth probability.</div><div style="margin-top:10px">${{q.dimensions.map(d=>`<div class="dimension"><div><b>${{niEsc(niTitle(d.name))}}</b><div class="muted small">${{niEsc(d.explanation||'')}}</div></div><div class="bar"><span style="width:${{Math.max(0,Math.min(100,(d.score||0)*100))}}%"></span></div><span class="small">${{readinessLabel(d.score)}}</span></div>`).join('')}}</div>`;updateMetrics(lastState?JSON.parse(lastState):{{state:'ready'}})}}
function claimLabel(c){{return c.latest_verification?.label||'unverified'}}
function pdfClaimLink(c){{const p=c?.extraction_features?.document_provenance;if(!p||!Number.isInteger(p.page)||p.page<1)return '';const source=niSafeUrl(p.page_url||'');if(!source||source==='#')return '';return `<div class="notice ${{p.ocr_unverified?'warn':'neutral'}}" style="margin-top:10px"><b>Source location:</b> <a href="${{niEsc(source)}}" target="_blank" rel="noopener noreferrer">PDF page ${{p.page}}</a> · ${{p.ocr_unverified?'OCR text · manual review required':'Native text match'}} · Location only, not independent confirmation.</div>`}}
function renderDocumentReview(v){{const box=document.getElementById('pdfDocumentReview');const pages=Array.isArray(v?.document_pages)?v.document_pages:[];const tables=Array.isArray(v?.document_table_candidates)?v.document_table_candidates:[];if(!pages.length&&!v?.document_page_count){{box.hidden=true;box.innerHTML='';return}}box.hidden=false;const ocrPages=pages.filter(p=>p.ocr_unverified).length;const known=Number(v?.document_page_count)||pages.length;const emptyCount=Number(v?.document_pages_without_text)||0;const requiresReview=Boolean(v?.document_requires_review);const warnings=Array.isArray(v?.extraction_warnings)?v.extraction_warnings:[];const warningHtml=(requiresReview||emptyCount||v?.document_truncated||ocrPages||warnings.length)?`<div class="notice warn"><b>Review source extraction:</b> ${{v?.document_truncated?'Only part of the PDF was processed. ':''}}${{emptyCount?emptyCount+' page(s) have no extracted text. ':''}}${{ocrPages?ocrPages+' OCR page(s) require checking against the original image. ':''}}${{warnings.length?'Warnings: '+niEsc(warnings.slice(0,8).map(niTitle).join(' · ')):''}}<div class="small" style="margin-top:5px">Source locations and OCR are not independent fact checks.</div></div>`:'';const pageLinks=pages.slice(0,40).map(p=>{{const url=niSafeUrl(p.source_url||'');const safe=niEsc(url);return `<a class="button secondary" href="${{safe}}" target="_blank" rel="noopener noreferrer">Page ${{Number(p.page)||'?'}}${{p.ocr_unverified?' · OCR':''}}</a>`}}).join('');const tableHtml=tables.slice(0,8).map((t,i)=>{{const rows=Array.isArray(t.rows)?t.rows.slice(0,35):[];const url=niEsc(niSafeUrl(t.source_url||''));return `<details style="margin-top:12px"><summary>Unverified table candidate ${{i+1}} · page ${{Number(t.page)||'?'}}</summary><div class="notice warn">Automatically detected column spacing. Check every row and number against <a href="${{url}}" target="_blank" rel="noopener noreferrer">the original PDF page</a>; this is not verified evidence.</div><div style="overflow-x:auto"><table><tbody>${{rows.map(row=>`<tr>${{(Array.isArray(row.cells)?row.cells:[]).slice(0,8).map(cell=>`<td>${{niEsc(String(cell))}}</td>`).join('')}}</tr>`).join('')}}</tbody></table></div></details>`}}).join('');box.innerHTML=`<section class="panel" style="margin-bottom:16px"><div class="section-head"><h2>PDF document review</h2><span class="muted small">${{pages.length}} of ${{known}} pages inspected</span></div><p class="muted small">Page links and extracted cells are traceable source material; they do not establish whether a reported statement is true. ${{Number.isFinite(v?.document_text_page_ratio)?Math.round(v.document_text_page_ratio*100)+'% of processed pages have readable text; not a fact-check score.':''}}</p>${{warningHtml}}<div class="toolbar" style="margin-top:12px;flex-wrap:wrap">${{pageLinks||'No page anchors available.'}}</div>${{tables.length?`<div class="section-head" style="margin-top:18px"><h3>Tables requiring manual review</h3><span class="muted small">${{tables.length}} candidate(s)</span></div>${{tableHtml}}`:''}}</section>`}}

function renderClaims(){{const box=document.getElementById('claims');const filter=document.getElementById('claimFilter').value;let rows=(claimsData||[]).filter(c=>filter==='all'||claimLabel(c)===filter);if(!rows.length){{box.innerHTML='<div class="empty">No claims match this filter.</div>';renderEvidenceMap();return}}box.innerHTML=`<div class="stack">${{rows.map(c=>{{const label=claimLabel(c);const kind=label==='supported'?'good':label==='contradicted'?'bad':label==='unverified'?'neutral':'warn';const links=c.evidence_links||[];return `<details class="claim-card"><summary><div><b>${{niEsc(c.claim_text)}}</b><div class="muted small" style="margin-top:5px">${{niEsc(niTitle(c.extraction_features?.claim_type||'claim'))}} · ${{links.length}} evidence link${{links.length===1?'':'s'}}</div></div>${{niPill(niTitle(label),kind)}}</summary><div class="claim-body">${{pdfClaimLink(c)}}${{links.length?`<div class="evidence-list">${{links.map(e=>`<div class="evidence-item"><div class="pill-row">${{niPill(niTitle(e.relationship||'context'),'neutral')}}${{niPill(niTitle(e.source_type||'source'),'neutral')}}</div><div style="margin-top:6px"><a href="${{niEsc(niSafeUrl(e.source_url))}}" target="_blank" rel="noopener noreferrer">${{niEsc(e.source_url)}}</a></div></div>`).join('')}}</div>`:'<p class="muted small">No evidence links are attached yet.</p>'}}<div class="toolbar" style="margin-top:12px"><a class="button secondary" href="/claims/${{niEsc(c.id)}}/investigation">Open claim investigation</a></div></div></details>`}}).join('')}}</div>`;renderEvidenceMap()}}
function renderEvidenceMap(){{if(!claimsData)return;const rows=[];for(const c of claimsData)for(const e of (c.evidence_links||[]))rows.push({{claim:c.claim_text,label:claimLabel(c),...e}});const box=document.getElementById('evidenceMap');if(!rows.length){{box.innerHTML='<div class="empty">No evidence relationships have been attached yet.</div>';return}}box.innerHTML=rows.slice(0,80).map(e=>`<div class="evidence-item"><div class="pill-row">${{niPill(niTitle(e.relationship||'context'))}}${{niPill(niTitle(e.source_type||'source'),'neutral')}}</div><div class="small" style="margin-top:7px"><b>Claim:</b> ${{niEsc(e.claim)}}</div><div class="small" style="margin-top:5px"><a href="${{niEsc(niSafeUrl(e.source_url))}}" target="_blank" rel="noopener noreferrer">Open evidence source</a></div></div>`).join('')}}
function historyItems(h){{if(!h)return[];return [...(h.same_event_history||[]).map(x=>({{...x,_channel:'same event'}})),...(h.internal_matches||[]).map(x=>({{...x,_channel:'internal corpus'}})),...(h.external_matches||[]).map(x=>({{...x,_channel:x.provider||'external'}}))]}}
function renderHistory(h){{const change=document.getElementById('changeSummary'),top=document.getElementById('topHistory'),timeline=document.getElementById('timeline');if(!h){{change.innerHTML='<div class="notice">Historical enrichment is still running. This page will update automatically.</div>';top.innerHTML=timeline.innerHTML='<div class="empty">No historical context yet.</div>';updateMetrics(lastState?JSON.parse(lastState):{{state:'enriching'}});return}}const s=h.context_summary||{{}};change.innerHTML=`<div class="notice"><b>${{niEsc(humanPattern(s.change_pattern))}}</b><div class="small" style="margin-top:6px">${{s.changed_claim_family_count||0}} changed claim families · ${{s.new_claim_family_count||0}} new · ${{s.recurring_claim_family_count||0}} recurring.</div></div>`;const items=historyItems(h);const ranked=[...items].sort((a,b)=>(b.relevance_score||0)-(a.relevance_score||0));top.innerHTML=ranked.slice(0,6).map(x=>timelineItem(x,true)).join('')||'<div class="empty">No strong prior reporting found.</div>';renderTimeline(items);updateMetrics(lastState?JSON.parse(lastState):{{state:'ready'}})}}
function timelineItem(x,ranked=false){{const title=x.title||x.claim_text||'Historical record';const when=x.published_at||x.retrieved_at;const source=x.publisher||x.source_name||x.provider||x._channel||'source';return `<div class="timeline-item"><b>${{niEsc(title)}}</b><div class="timeline-time">${{niDate(when)}} · ${{niEsc(source)}}${{ranked&&x.relevance_label?` · ${{niEsc(niTitle(x.relevance_label))}} linkage`:''}}</div></div>`}}
function renderTimeline(items=historyItems(historyData)){{const order=document.getElementById('timelineOrder').value;items=[...items].sort((a,b)=>new Date(a.published_at||a.retrieved_at||0)-new Date(b.published_at||b.retrieved_at||0));if(order==='desc')items.reverse();document.getElementById('timeline').innerHTML=items.slice(0,60).map(x=>timelineItem(x)).join('')||'<div class="empty">No historical timeline yet.</div>'}}
document.getElementById('claimFilter').addEventListener('change',renderClaims);document.getElementById('timelineOrder').addEventListener('change',()=>renderTimeline());
function connect(){{const es=new EventSource(`/api/v1/articles/${{articleId}}/intelligence-stream`);es.onopen=()=>{{document.getElementById('liveDot').classList.add('live');document.getElementById('liveText').textContent='Live'}};es.addEventListener('intelligence_state',e=>{{if(lastState&&lastState!==e.data){{loadCore().then(loadAnalystPanels).catch(()=>{{}})}}lastState=e.data}});es.onerror=()=>{{document.getElementById('liveDot').classList.remove('live');document.getElementById('liveText').textContent='Reconnecting'}}}}
loadCore().then(()=>loadAnalystPanels()).then(connect).catch(()=>{{}});
</script>"""
    return render_app_page(title="Article Intelligence", body=body, active="news", role=role, scripts=scripts)


@router.get("/events/{event_id}/intelligence", response_class=HTMLResponse)
async def event_intelligence_dashboard(event_id: UUID, auth: ViewerAuth) -> str:
    role = getattr(getattr(auth, "role", None), "value", "viewer")
    workspace_button = (
        f'<a class="button ghost" href="/investigations?add_type=event&add_id={event_id}">Add to workspace</a>'
        if Permission.CLAIMS_VIEW.value in auth.permissions
        else ""
    )
    briefing_button = (
        f'<a class="button" href="/events/{event_id}/briefing">Grounded briefing</a>'
        if Permission.CLAIMS_VIEW.value in auth.permissions
        else ""
    )
    body = f"""
<section class="page-head"><div><div class="eyebrow">Event dossier</div><h1 id="eventTitle">Loading event…</h1><p id="eventMeta" class="lead"></p></div><div class="toolbar">{workspace_button}{briefing_button}<a class="button ghost" href="/events">All events</a><a class="button secondary" href="/news">News</a></div></section>
<section id="eventAlert" aria-live="polite"></section>
<section class="grid four" id="eventMetrics"><div class="metric"><div class="skeleton"></div></div><div class="metric"><div class="skeleton"></div></div><div class="metric"><div class="skeleton"></div></div><div class="metric"><div class="skeleton"></div></div></section>
<section class="grid two" style="margin-top:18px">
  <div class="panel"><div class="section-head"><div><h2>Claim verification posture</h2><div class="muted small">Stored evidence assessments for claims in the latest article versions. Not a universal truth score.</div></div></div><div id="verificationPosture"><div class="skeleton" style="height:115px"></div></div></div>
  <div class="panel"><div class="section-head"><div><h2>Source diversity</h2><div class="muted small">Publisher coverage for reporting currently linked to this event.</div></div></div><div id="sourceDiversity"><div class="skeleton" style="height:115px"></div></div></div>
</section>
<section class="panel" style="margin-top:18px"><div class="section-head"><div><h2>Evidence lineage intelligence</h2><div class="muted small">Deduplicated evidence identity across current event claims. This is not the same as publisher count.</div></div></div><div id="lineageIntelligence"><div class="skeleton" style="height:120px"></div></div></section>
<section class="grid two" style="margin-top:18px">
  <div class="panel"><div class="section-head"><div><h2>Event signals</h2><div class="muted small">Reporting-change signals; they are not factual verdicts.</div></div></div><div id="eventSignals"><div class="skeleton" style="height:100px"></div></div></div>
  <div class="panel"><div class="section-head"><div><h2>Timeline semantics</h2><div class="muted small">How event chronology is being constructed.</div></div></div><div id="timelineSemantics"><div class="skeleton" style="height:100px"></div></div></div>
</section>
<section class="panel" id="claimPanel" style="margin-top:18px"><div class="section-head"><div><h2>Claims in current reporting</h2><div class="muted small">Atomic claims from the latest version of each linked article.</div></div><div class="toolbar"><select id="claimStatusFilter" aria-label="Filter event claims"><option value="all">All claim states</option><option value="supported">Supported</option><option value="contradicted">Contradicted</option><option value="disputed">Disputed</option><option value="unsupported">Unsupported</option><option value="not_checkable">Not checkable</option><option value="unverified">Unverified</option></select><span id="claimCount" class="muted small"></span></div></div><div id="eventClaims" class="stack"><div class="skeleton" style="height:170px"></div></div></section>
<section class="panel" style="margin-top:18px"><div class="section-head"><div><h2>Material timeline</h2><div class="muted small">Article observations and version changes in event time order.</div></div><span id="timelineCount" class="muted small"></span></div><div id="eventTimeline" class="timeline"><div class="skeleton" style="height:180px"></div></div></section>
<section class="panel" style="margin-top:18px"><div class="section-head"><div><h2>Linked reporting</h2><div class="muted small">All currently assigned articles for this event.</div></div><span id="articleCount" class="muted small"></span></div><div id="eventArticles" class="article-list"><div class="skeleton" style="height:160px"></div></div></section>
"""
    event_id_text = str(event_id)
    scripts = f"""<script>{COMMON_JS}
const eventId={event_id_text!r};let dossierData=null;
function eventPattern(v){{const map={{mostly_new_reporting:'Mostly new reporting',material_update:'Material update',continuity_with_prior_reporting:'Continuity',possible_conflict_or_revision:'Possible conflict / revision',no_checkable_claims:'No checkable claims'}};return map[v]||niTitle(v||'Analysis pending')}}
function verificationKind(v){{const label=String(v||'').toLowerCase();if(label==='supported')return 'good';if(['contradicted','misleading'].includes(label))return 'bad';if(['disputed','unsupported','not_checkable','insufficient_evidence'].includes(label))return 'warn';return 'neutral'}}
function timelinePoint(x){{const articleHref=x.article_id?`/articles/${{niEsc(x.article_id)}}/intelligence`:null;const title=niEsc(x.title||'Event update');const label=articleHref?`<a href="${{articleHref}}">${{title}}</a>`:title;const changes=(x.material_change_count||0)+(x.numeric_change_count||0)+(x.temporal_change_count||0);const details=[niTitle(x.point_type||'report'),`${{x.claim_count||0}} claims`,changes?`${{changes}} material signals`:null].filter(Boolean).join(' · ');return `<div class="timeline-item"><b>${{label}}</b><div class="timeline-time">${{niDate(x.occurred_at||x.published_at)}} · ${{niEsc(details)}}</div></div>`}}
function renderDossier(dossier){{dossierData=dossier;if(!dossier){{document.getElementById('verificationPosture').innerHTML='<div class="notice">Claim-level dossier requires analyst access. Event reporting and chronology remain available below.</div>';document.getElementById('sourceDiversity').innerHTML='<div class="muted small">Publisher-level coverage is shown in the headline metrics. Detailed source breakdown requires analyst access.</div>';document.getElementById('lineageIntelligence').innerHTML='<div class="notice">Evidence-lineage analysis requires analyst access.</div>';document.getElementById('claimPanel').hidden=true;return}}const counts=dossier.verification_counts||{{}};const entries=Object.entries(counts).sort((a,b)=>b[1]-a[1]);document.getElementById('verificationPosture').innerHTML=`<div class="grid two"><div class="metric"><div class="label">Evidence-assessed</div><div class="value">${{dossier.verified_claim_count}}</div><div class="hint">Decided support / contradiction / dispute labels</div></div><div class="metric"><div class="label">Unresolved / abstained</div><div class="value">${{dossier.unresolved_claim_count}}</div><div class="hint">Insufficient, unsupported or not-checkable</div></div></div><div class="pill-row" style="margin-top:12px">${{entries.map(([label,count])=>niPill(`${{niTitle(label)}}: ${{count}}`,verificationKind(label))).join('')}}</div><div class="muted small" style="margin-top:10px">${{dossier.independent_evidence_link_count}} qualifying evidence links · ${{dossier.independent_lineage_count||0}} observed lineages · ${{dossier.primary_evidence_link_count}} primary-source links · ${{dossier.contradiction_evidence_link_count}} contradiction/dispute links</div>`;const publishers=dossier.publisher_breakdown||[];document.getElementById('sourceDiversity').innerHTML=publishers.length?`<div class="stack">${{publishers.slice(0,8).map(p=>`<div class="toolbar" style="justify-content:space-between"><span>${{niEsc(p.publisher_name)}}</span><span class="pill neutral">${{p.article_count}} reports</span></div>`).join('')}}</div>${{publishers.length>8?`<div class="muted small" style="margin-top:10px">+ ${{publishers.length-8}} more publishers</div>`:''}}`:'<div class="empty">No publisher breakdown available.</div>';const lineages=dossier.lineage_breakdown||[];document.getElementById('lineageIntelligence').innerHTML=`<div class="grid four"><div class="metric"><div class="label">Observed lineages</div><div class="value">${{dossier.independent_lineage_count||0}}</div><div class="hint">Deduplicated lineage keys</div></div><div class="metric"><div class="label">Qualifying links</div><div class="value">${{dossier.independent_evidence_link_count||0}}</div><div class="hint">Before lineage deduplication</div></div><div class="metric"><div class="label">Ownership-reduced</div><div class="value">${{dossier.ownership_reduced_evidence_link_count||0}}</div><div class="hint">Shared ownership caps independence</div></div><div class="metric"><div class="label">Circular / near-duplicate</div><div class="value">${{(dossier.circular_sourcing_link_count||0)+(dossier.near_duplicate_evidence_link_count||0)}}</div><div class="hint">Circular ${{dossier.circular_sourcing_link_count||0}} · near-duplicate ${{dossier.near_duplicate_evidence_link_count||0}}</div></div></div>${{lineages.length?`<div class="stack" style="margin-top:14px">${{lineages.slice(0,8).map(l=>`<div class="evidence-item"><div class="toolbar" style="justify-content:space-between"><div><b>${{niEsc(l.lineage_key)}}</b><div class="muted small">${{l.link_count}} links · ${{l.claim_count}} claims · max independence ${{Math.round((l.max_independence_score||0)*100)}}%</div></div><div class="pill-row">${{l.primary_source_present?niPill('Primary','good'):''}}${{l.shared_ownership_present?niPill('Shared ownership','warn'):''}}${{l.circular_sourcing_present?niPill('Circular sourcing','warn'):''}}</div></div></div>`).join('')}}</div>`:'<div class="empty" style="margin-top:14px">No evidence lineages have been recorded yet.</div>'}}`;renderClaims()}}
function renderClaims(){{if(!dossierData)return;const filter=document.getElementById('claimStatusFilter').value;const claims=(dossierData.claims||[]).filter(c=>{{const label=c.verification_label||'unverified';return filter==='all'||label===filter}});document.getElementById('claimCount').textContent=`${{claims.length}} shown`;document.getElementById('eventClaims').innerHTML=claims.slice(0,80).map(c=>`<details class="claim-card"><summary><div><div class="pill-row">${{niPill(niTitle(c.verification_label||'unverified'),verificationKind(c.verification_label))}}${{c.claim_type?niPill(niTitle(c.claim_type),'neutral'):''}}${{c.ownership_reduced_evidence_count?niPill(`${{c.ownership_reduced_evidence_count}} ownership-reduced`,'warn'):''}}${{c.circular_sourcing_count?niPill(`${{c.circular_sourcing_count}} circularity flag${{c.circular_sourcing_count===1?'':'s'}}`,'warn'):''}}${{c.near_duplicate_evidence_count?niPill(`${{c.near_duplicate_evidence_count}} near-duplicate signal${{c.near_duplicate_evidence_count===1?'':'s'}}`,'warn'):''}}</div><b style="display:block;margin-top:8px">${{niEsc(c.claim_text)}}</b><div class="muted small" style="margin-top:6px">From ${{niEsc(c.article_title)}}</div></div><span class="muted small">${{c.independent_lineage_count||0}} lineage${{(c.independent_lineage_count||0)===1?'':'s'}}</span></summary><div class="claim-body"><div class="grid four" style="margin-top:12px"><div class="metric"><div class="label">Evidence links</div><div class="value">${{c.evidence_link_count}}</div></div><div class="metric"><div class="label">Lineages</div><div class="value">${{c.independent_lineage_count||0}}</div><div class="hint">${{c.same_lineage_duplicate_count||0}} repeated-link duplicates</div></div><div class="metric"><div class="label">Primary</div><div class="value">${{c.primary_evidence_count}}</div></div><div class="metric"><div class="label">Contradiction</div><div class="value">${{c.contradiction_evidence_count}}</div></div></div><div class="toolbar" style="margin-top:12px"><a class="button" href="/claims/${{niEsc(c.id)}}/investigation">Investigate claim</a><a class="button secondary" href="/articles/${{niEsc(c.article_id)}}/intelligence">Article evidence</a>${{c.verification_confidence!=null?`<span class="muted small">Stored confidence ${{Math.round(c.verification_confidence*100)}}%</span>`:''}}</div></div></details>`).join('')||'<div class="empty">No claims match this filter.</div>'}}
async function load(){{try{{const [e,timeline,dossier]=await Promise.all([niApi(`/api/v1/events/${{eventId}}`),niOptional(`/api/v1/events/${{eventId}}/timeline`),niOptional(`/api/v1/events/${{eventId}}/dossier`)]);document.getElementById('eventTitle').textContent=e.title;document.title=`${{e.title}} · Event Dossier`;document.getElementById('eventMeta').textContent=`First detected ${{niDate(e.first_detected_at)}} · last material change ${{niDate(e.last_material_change_at)}}`;const rows=[...(e.articles||[])].sort((a,b)=>new Date(b.published_at||b.first_observed_at)-new Date(a.published_at||a.first_observed_at));const publishers=new Set(rows.map(a=>a.publisher_id).filter(Boolean)).size;const materialUpdates=rows.filter(a=>a.historical_change_pattern==='material_update').length;const conflictSignals=rows.filter(a=>a.historical_change_pattern==='possible_conflict_or_revision').length;document.getElementById('eventMetrics').innerHTML=`<div class="metric"><div class="label">Lifecycle</div><div class="value">${{niEsc(niTitle(e.lifecycle_status))}}</div><div class="hint">${{niEsc(niTitle(e.assignment_status))}} assignment</div></div><div class="metric"><div class="label">Linked reports</div><div class="value">${{rows.length}}</div><div class="hint">Current event membership</div></div><div class="metric"><div class="label">Publishers</div><div class="value">${{publishers}}</div><div class="hint">Distinct reporting outlets</div></div><div class="metric"><div class="label">Latest claims</div><div class="value">${{dossier?dossier.latest_claim_count:'—'}}</div><div class="hint">${{dossier?'Latest article versions':'Analyst access required'}}</div></div>`;renderDossier(dossier);document.getElementById('eventSignals').innerHTML=`<div class="pill-row">${{niPill(`${{materialUpdates}} material updates`,materialUpdates?'warn':'neutral')}}${{niPill(`${{conflictSignals}} conflict / revision signals`,conflictSignals?'warn':'neutral')}}${{niPill(`${{rows.filter(a=>a.historical_change_pattern==='mostly_new_reporting').length}} mostly-new reports`,'neutral')}}</div><p class="muted small" style="margin:12px 0 0">These counts describe reporting-change patterns. Inspect claim evidence before drawing factual conclusions.</p>`;if(conflictSignals)document.getElementById('eventAlert').innerHTML='<div class="notice warn"><b>Review suggested.</b> One or more linked reports contain a possible conflict or revision signal.</div>';if(timeline){{document.getElementById('timelineSemantics').innerHTML=`<div><b>${{niEsc(niTitle(timeline.timeline_basis))}}</b></div><p class="muted small">${{niEsc(timeline.time_semantics_note||'Timeline is based on stored event and article timestamps.')}}</p><div class="pill-row">${{niPill(`${{timeline.publisher_count}} publishers`,'neutral')}}${{niPill(`${{timeline.article_count}} articles`,'neutral')}}</div>`;const points=timeline.timeline_points||[];document.getElementById('timelineCount').textContent=`${{points.length}} timeline points`;document.getElementById('eventTimeline').innerHTML=points.map(timelinePoint).join('')||'<div class="empty">No timeline points have been recorded yet.</div>'}}else{{document.getElementById('timelineSemantics').innerHTML='<div class="notice">Detailed event chronology requires analyst access. Linked reporting is still shown below.</div>';document.getElementById('timelineCount').textContent=`${{rows.length}} report observations`;document.getElementById('eventTimeline').innerHTML=[...rows].reverse().map(a=>timelinePoint({{occurred_at:a.published_at||a.first_observed_at,point_type:'article_observed',article_id:a.id,title:a.title,claim_count:0}})).join('')||'<div class="empty">No event observations are available.</div>'}}document.getElementById('articleCount').textContent=`${{rows.length}} linked stories`;document.getElementById('eventArticles').innerHTML=rows.map(a=>`<article class="story-card"><div><div class="pill-row">${{a.historical_change_pattern?niPill(eventPattern(a.historical_change_pattern),a.historical_change_pattern==='possible_conflict_or_revision'?'warn':'neutral'):''}}${{a.latest_extraction_fidelity_label?niPill(`Publisher fidelity: ${{niTitle(a.latest_extraction_fidelity_label)}}`,String(a.latest_extraction_fidelity_label).toLowerCase()==='strong'?'good':'warn'):''}}</div><h2><a href="/articles/${{niEsc(a.id)}}/intelligence">${{niEsc(a.title)}}</a></h2><div class="muted small">${{niDate(a.published_at||a.first_observed_at)}} · ${{niEsc(a.language||'language unknown')}} · ${{niEsc(a.word_count||'—')}} words</div></div><div class="story-side"><div class="pattern">${{niEsc(eventPattern(a.historical_change_pattern))}}</div><div style="margin-top:14px"><a class="button secondary" href="/articles/${{niEsc(a.id)}}/intelligence">Open story</a></div></div></article>`).join('')||'<div class="empty">No articles are attached to this event.</div>'}}catch(err){{document.getElementById('eventTitle').textContent='Unable to load event';document.getElementById('eventTimeline').innerHTML=document.getElementById('eventArticles').innerHTML=`<div class="error-box">${{niEsc(err.message)}}</div>`}}}}document.getElementById('claimStatusFilter').addEventListener('change',renderClaims);load();
</script>"""
    return render_app_page(title="Event Dossier", body=body, active="events", role=role, scripts=scripts)
